#include <string>

class Solution {
public:
    long long countVowels(std::string word) {
        long long ans = 0;
        long long n = word.size();
        for (long long i = 0; i < n; ++i) {
            char c = word[i];
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                ans += (i + 1) * (n - i);
            }
        }
        return ans;
    }
};

class Solution {
    public long countVowels(String word) {
        long ans = 0;
        long n = word.length();
        for (long i = 0; i < n; i++) {
            char c = word.charAt((int) i);
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                ans += (i + 1) * (n - i);
            }
        }
        return ans;
    }
}

/**
 * @param {string} word
